import {Renderer} from './world.js';
import {currentMap,tile,resourceAt,TROOPS,STRUCTURES,STOCK_NAMES,HAZARDS,clock,convoyPositions} from './horizons.js';
import {EARLY,earlyBuilding,earlyUnit} from './horizons-art.js';
import {MATERIALS} from './sectors.js';
const colors=['#8ea96e','#bca577','#9eaea0','#8ca578','#9b947f','#72987b'];
export class HorizonsRenderer extends Renderer{
 constructor(canvas){super(canvas);this.layer=0;this.lastTileCount=0;}
 groundHeight(x,y){return this.layer?0:(tile(this.map,x,y)?.h||0)*10;}
 tileAt(px,py){const raw=this.unproject(px,py),candidates=[],t=52*this.scale*this.camera.zoom,m=this.map;if(!m)return{x:-1,y:-1};for(let x=Math.max(0,Math.floor(raw.x)-2);x<=Math.min(m.size-1,Math.ceil(raw.x)+15);x++)for(let y=Math.max(0,Math.floor(raw.y)-2);y<=Math.min(m.size-1,Math.ceil(raw.y)+15);y++){const z=!this.layer&&m.fog[y*m.size+x]?(tile(m,x,y)?.h||0)*10:0,p=this.p(x+.5,y+.5,z);if(Math.abs(px-p.x)/(t/2)+Math.abs(py-p.y)/(t/4)<=1)candidates.push({x,y});}return candidates.sort((a,b)=>(b.x+b.y)-(a.x+a.y))[0]||{x:Math.floor(raw.x),y:Math.floor(raw.y)};}
 draw(state,{selected=[],tool=null,hover=null,selectionBox=null}={}){
  const m=currentMap(state);this.map=m;this.activeMap={size:m.size,terrain:m.terrain};const c=this.ctx;c.setTransform(this.dpr,0,0,this.dpr,0,0);this.time=performance.now()/1000;const bounds=this.bounds(m.size),layer=this.layer,key=[m.id,m.terrain.revision,m.fog.revision,this.camera.x,this.camera.y,this.camera.zoom,this.w,this.h,layer,(m.voxelRevision||0)].join('|');
  this.lastTileCount=Math.max(0,bounds.x1-bounds.x0+1)*Math.max(0,bounds.y1-bounds.y0+1);const known=(x,y)=>!!m.fog[y*m.size+x],visible=(x,y)=>!!m.sight?.[Math.floor(y)*m.size+Math.floor(x)];
  const undergroundSeen=(x,y)=>Object.hasOwn(m.voxels,x+':'+y+':'+layer)||m.units.some(u=>u.depth===layer&&u.hp>0&&Math.hypot(u.x-x,u.y-y)<4);
  if(key!==this.groundKey){this.ground.width=this.canvas.width;this.ground.height=this.canvas.height;const g=this.ground.getContext('2d');g.setTransform(this.dpr,0,0,this.dpr,0,0);this.ctx=g;g.fillStyle=layer?'#242e32':'#1c3039';g.fillRect(0,0,this.w,this.h);for(let sum=bounds.x0+bounds.y0;sum<=bounds.x1+bounds.y1;sum++)for(let x=bounds.x0;x<=bounds.x1;x++){const y=sum-x;if(y<bounds.y0||y>bounds.y1||!known(x,y)||!this.onScreen(x,y,170))continue;const t=tile(m,x,y,layer);let color=layer?undergroundSeen(x,y)?MATERIALS[t.material]?.color||'#535c60':'#39474b':t.kind==='water'?'#527f98':t.kind==='forest'?'#6f955d':t.kind==='bridge'?'#bca577':['path','rail','pipe'].includes(t.kind)?'#b5aa87':t.kind==='mountain'?'#8e9d99':t.kind==='cliff'?'#a2967d':t.kind==='wall'?'#a8a38c':colors[m.biome];
   this.tile(x,y,layer?0:t.h,color);if(layer&&['air','stairs','support'].includes(t.material))this.poly([this.p(x,y,2),this.p(x+1,y,2),this.p(x+1,y+1,2),this.p(x,y+1,2)],'#293e43','#9da88b77');if(!layer&&t.kind==='water')this.line(this.p(x+.1,y+.4,-9),this.p(x+.8,y+.4,-9),'#abd0d655');if(t.kind==='bridge'||t.kind==='rail'){for(let a=0;a<4;a++)this.line(this.p(x+a*.25,y,3),this.p(x+a*.25,y+1,3),t.kind==='rail'?'#74766a':'#ddc491',2);this.line(this.p(x,y+.15,4),this.p(x+1,y+.15,4),'#d1d6c0',1);this.line(this.p(x,y+.85,4),this.p(x+1,y+.85,4),'#d1d6c0',1);}if(t.kind==='pipe')this.box(x,y+.3,1,.35,6,'#8aabac',t.h*10);
  }this.ctx=c;this.groundKey=key;}
  c.clearRect(0,0,this.w,this.h);c.drawImage(this.ground,0,0,this.w,this.h);const objects=[];
  if(!layer){for(let y=bounds.y0;y<=bounds.y1;y++)for(let x=bounds.x0;x<=bounds.x1;x++){if(!known(x,y)||!this.onScreen(x,y,170))continue;const t=tile(m,x,y),z=t.h*10;if(t.kind==='mountain')objects.push({d:x+y,draw:()=>this.mountain(x,y,t.h,m.biome)});else if(t.kind==='wall')objects.push({d:x+y,draw:()=>this.box(x+.05,y+.05,.9,.9,35,'#a8ab96',z)});else if(t.kind==='forest')objects.push({d:x+y,draw:()=>this.tree(x+.5,y+.5,((x*7+y*13)%31)/31,z)});
   const node=resourceAt(m,x,y);if(node&&t.kind!=='forest')objects.push({d:x+y+.2,draw:()=>{if(node.resource==='wood')this.tree(x+.5,y+.5,.5,z);else if(node.resource==='food'){for(let i=0;i<4;i++)this.circle(x+.25+(i%2)*.4,y+.25+Math.floor(i/2)*.4,z+6,5,'#babf68');}else{this.box(x+.12,y+.2,.5,.5,10,'#b8b7a1',z);this.box(x+.45,y+.55,.4,.35,7,'#8f9995',z);}}});}
   for(const b of m.buildings)if(b.hp>0&&this.onScreen(b.x,b.y,200))objects.push({d:b.x+b.y+2,draw:()=>{const spec=STRUCTURES[b.type];if(EARLY.has(b.type)){const p=this.groundPoint(b.x+spec.size/2,b.y+spec.size/2);earlyBuilding(c,b.type,p.x,p.y,this.scale*this.camera.zoom);}else this.building({...b,type:spec.art,z:this.groundHeight(b.x,b.y),readyAt:0},selected.includes(b.id));if(b.progress<1){const p=this.groundPoint(b.x+1,b.y+1);this.label('OBRA '+Math.floor(b.progress*100)+'%',p.x,p.y-65*this.scale*this.camera.zoom,{size:8});}}});
   for(const f of m.factions)if(f.discovered&&this.onScreen(f.x,f.y,220))objects.push({d:f.x+f.y,draw:()=>{this.building({type:f.owner==='player'?'embassy':f.hostile?'barracks':'market',x:f.x-1,y:f.y-1,level:Math.min(5,f.era),hp:f.hp,enemy:f.hostile,z:this.groundHeight(f.x,f.y)});const p=this.groundPoint(f.x,f.y);this.label(f.owner==='player'?'CONQUISTADA':f.allied?'ALIADA':f.hostile?'BASE HOSTIL':'ALDEA',p.x,p.y-84*this.scale*this.camera.zoom,{color:f.hostile?'#ffb19a':'#bde4bd',size:8});if(visible(f.x,f.y)&&f.hp<f.maxHp)this.health(f.x,f.y,95,f.hp/f.maxHp,true);}});
   for(const e of m.exits)if(e.discovered&&this.onScreen(e.x,e.y,140))objects.push({d:e.x+e.y,draw:()=>{const p=this.groundPoint(e.x,e.y);this.circle(e.x,e.y,5,6,'#d8cf93');this.label(m.kind==='ocean'?e.id==='origin'?'REGRESO':'TIERRA AVISTADA':'SALIDA AL OCÉANO',p.x,p.y-32*this.scale*this.camera.zoom,{size:8});}});
  }else{for(let y=bounds.y0;y<=bounds.y1;y++)for(let x=bounds.x0;x<=bounds.x1;x++){if(!known(x,y)||!undergroundSeen(x,y)||!this.onScreen(x,y,130))continue;const t=tile(m,x,y,layer);if(t.material==='support')objects.push({d:x+y,draw:()=>{this.box(x+.1,y+.1,.1,.1,34,'#b68f61');this.box(x+.8,y+.8,.1,.1,34,'#b68f61');this.box(x+.1,y+.1,.8,.8,3,'#b68f61',34);}});if(t.material==='stairs')objects.push({d:x+y,draw:()=>{for(let i=0;i<5;i++)this.box(x+.1,y+i*.16,.8,.13,3+i*3,'#cdbd8f');}});}}
  for(const u of m.units)if(u.hp>0&&!u.embarked&&u.depth===layer&&this.onScreen(u.x,u.y,100))objects.push({d:u.x+u.y+.1,draw:()=>{const art=TROOPS[u.type].art;if(['settler','raft','galley'].includes(u.type)){const p=this.groundPoint(u.x,u.y);earlyUnit(c,u.type,p.x,p.y,this.scale*this.camera.zoom,u.walking,this.time);}else this.unit({...u,type:art});if(selected.includes(u.id)){const p=this.groundPoint(u.x,u.y),sc=this.scale*this.camera.zoom;c.strokeStyle='#d3e9a4';c.lineWidth=2;c.beginPath();c.ellipse(p.x,p.y+3*sc,17*sc,8*sc,0,0,7);c.stroke();if(u.order?.x!==undefined){const q=this.groundPoint(u.order.x,u.order.y);c.setLineDash([5,5]);this.line(p,q,'#d3e9a477');c.setLineDash([]);}const q=this.p(u.x,u.y,this.groundHeight(u.x,u.y)+48);this.label(TROOPS[u.type].civilian?'COLONO':TROOPS[u.type].name.toUpperCase(),q.x,q.y,{size:7});}}});
  if(!layer){for(const e of m.enemies||[])if(e.hp>0&&visible(e.x,e.y)&&this.onScreen(e.x,e.y))objects.push({d:e.x+e.y,draw:()=>this.unit({...e,type:TROOPS[e.type].art},true)});for(const u of convoyPositions(state))if(known(Math.floor(u.x),Math.floor(u.y))&&this.onScreen(u.x,u.y))objects.push({d:u.x+u.y,draw:()=>{const p=this.groundPoint(u.x,u.y);if(u.kind==='air'||u.kind==='train')earlyUnit(c,u.kind==='air'?'plane':'train',p.x,p.y,this.scale*this.camera.zoom,true,this.time);else this.unit({...u,type:TROOPS[u.type].art,hp:1,maxHp:1,walking:true});this.label((u.kind==='train'?'TREN':u.kind==='air'?'CARGA AÉREA':'CONVOY')+' · '+u.cargo,p.x,p.y-50*this.scale*this.camera.zoom,{size:7});}});}
  objects.sort((a,b)=>a.d-b.d).forEach(o=>o.draw());
  if(!layer){for(let y=bounds.y0;y<=bounds.y1;y++)for(let x=bounds.x0;x<=bounds.x1;x++)if(known(x,y)&&!visible(x,y)&&this.onScreen(x,y,130)){const z=this.groundHeight(x,y)+1;this.poly([this.p(x,y,z),this.p(x+1,y,z),this.p(x+1,y+1,z),this.p(x,y+1,z)],'#152e3d66');}}
  if(clock(state).night&&!layer){c.fillStyle='#101d382b';c.fillRect(0,0,this.w,this.h);}
  for(const e of state.events.filter(e=>e.map===m.id)){const type=HAZARDS[e.type];if(!e.radius){if(e.starts<=state.time){const g=c.createLinearGradient(0,0,this.w,this.h);g.addColorStop(0,e.type==='aurora'?'#78dcb42b':'#dba96722');g.addColorStop(.5,'#b19ceb15');g.addColorStop(1,'#00000000');c.fillStyle=g;c.fillRect(0,0,this.w,this.h);}continue;}if(!known(Math.floor(e.x),Math.floor(e.y))||!this.onScreen(e.x,e.y,200))continue;const p=this.groundPoint(e.x,e.y),sc=this.scale*this.camera.zoom;c.strokeStyle=type.color;c.fillStyle=type.color+'22';c.beginPath();c.ellipse(p.x,p.y,e.radius*26*sc,e.radius*13*sc,0,0,7);c.fill();c.stroke();this.label(type.name.toUpperCase()+' · '+(e.starts>state.time?'EVACÚA '+Math.ceil(e.starts-state.time)+'s':'PELIGRO'),p.x,p.y-45*sc,{size:8,color:type.color});}
  if(hover&&tool&&known(hover.x,hover.y)){const x=hover.x,y=hover.y,z=this.groundHeight(x,y)+2,size=STRUCTURES[tool]?.size||1;this.poly([this.p(x,y,z),this.p(x+size,y,z),this.p(x+size,y+size,z),this.p(x,y+size,z)],'#e2dda333','#eee1b5',2);}
  if(selectionBox){c.fillStyle='#bad7b329';c.strokeStyle='#d2e5b3';c.fillRect(selectionBox.x,selectionBox.y,selectionBox.w,selectionBox.h);c.strokeRect(selectionBox.x,selectionBox.y,selectionBox.w,selectionBox.h);}
  const now=performance.now();this.shots=this.shots.filter(v=>now-v.at<360);for(const shot of this.shots){c.globalAlpha=1-(now-shot.at)/360;this.line(this.p(shot.x,shot.y,30+this.groundHeight(shot.x,shot.y)),this.p(shot.tx,shot.ty,25+this.groundHeight(shot.tx,shot.ty)),shot.enemy?'#e9a17d':'#e9d9a4',2);}c.globalAlpha=1;if(this.motion.size>500)this.motion.clear();
 }
}
